#!/usr/bin/env node
/**
 * The published numbers are checked against a stored file. Nothing checked the file.
 *
 * `verify:docs` compares every figure in the readme to `eval/results/*.json` — the
 * held-out precision, the H1–H3 verdicts, the grid size, the lift. That closes the gap
 * between the prose and the harness output, and leaves open the one behind it: the
 * harness output is a *committed artifact*, regenerated by hand. Change a detector and
 * every gate stays green while `breach.json` describes the detector you used to have.
 *
 * That is not hypothetical here. This week moved the breach engine (a seventh detector,
 * for `guarantee` and `warranty`), the projection that counts a derived verdict, and the
 * money a derived breach is worth. Re-running the harnesses by hand afterwards found all
 * five deterministic reports byte-identical — which is the right answer, and was worth
 * nothing as a guarantee, because the next change gets no such check.
 *
 * So: re-run them and insist the numbers come back the same.
 *
 * `latency.json` is excluded on purpose. It is the one report that is a property of the
 * machine rather than of the code — it carries the core count and load average it was
 * taken under — and re-running it would fail on a quiet laptop as readily as on a busy
 * one. The readme quotes no latency figure for the same reason.
 *
 * The working tree is left exactly as it was found, drift or no drift: the reports are
 * copied aside, the harnesses overwrite them, the comparison runs, and the copies go
 * back. A gate that edits what it is checking is not a gate.
 */
import { spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const RESULTS = join(REPO_ROOT, "eval", "results");

/** The five reports that are a pure function of the code and a fixed seed. */
const DETERMINISTIC = ["extraction", "breach", "recourse", "learning", "robustness"];

/**
 * Compare parsed JSON rather than bytes.
 *
 * Numbers still have to match exactly — that is the whole point — but a difference in
 * indentation or key order would be a false alarm about formatting, not about a figure.
 */
function difference(before, after, path = "") {
  if (Object.is(before, after)) return undefined;

  const shape = (value) =>
    value === null ? "null" : Array.isArray(value) ? "array" : typeof value;
  if (shape(before) !== shape(after)) {
    return `${path || "(root)"}: ${shape(before)} became ${shape(after)}`;
  }

  if (Array.isArray(before)) {
    if (before.length !== after.length) {
      return `${path}: ${before.length} entries became ${after.length}`;
    }
    for (let index = 0; index < before.length; index += 1) {
      const found = difference(before[index], after[index], `${path}[${index}]`);
      if (found !== undefined) return found;
    }
    return undefined;
  }

  if (shape(before) === "object") {
    const keys = [...new Set([...Object.keys(before), ...Object.keys(after)])];
    for (const key of keys) {
      if (!(key in before)) return `${path}.${key}: appeared`;
      if (!(key in after)) return `${path}.${key}: disappeared`;
      const found = difference(before[key], after[key], `${path}.${key}`);
      if (found !== undefined) return found;
    }
    return undefined;
  }

  return `${path || "(root)"}: ${JSON.stringify(before)} became ${JSON.stringify(after)}`;
}

const stored = new Map();
for (const name of DETERMINISTIC) {
  const path = join(RESULTS, `${name}.json`);
  try {
    stored.set(name, { path, text: readFileSync(path, "utf8") });
  } catch {
    process.stdout.write(
      `  FAIL ${name}.json is not there — run \`pnpm eval:all\` and commit the result\n`,
    );
    process.exit(1);
  }
}

process.stdout.write("\n--- the committed reports, re-derived ---\n");

const failures = [];
try {
  for (const name of DETERMINISTIC) {
    const run = spawnSync("pnpm", ["--filter", "@owed/eval", name], {
      cwd: REPO_ROOT,
      encoding: "utf8",
      // The harnesses print their own tables; this gate only wants the numbers.
      stdio: ["ignore", "pipe", "pipe"],
    });

    if (run.status !== 0) {
      failures.push(`${name} harness exited ${run.status}`);
      process.stdout.write(`  FAIL ${name} — harness exited ${run.status}\n`);
      const detail = `${run.stdout ?? ""}${run.stderr ?? ""}`.trim().split("\n").slice(-4);
      for (const line of detail) process.stdout.write(`       ${line}\n`);
      continue;
    }

    const { path, text } = stored.get(name);
    const found = difference(JSON.parse(text), JSON.parse(readFileSync(path, "utf8")));
    if (found === undefined) {
      process.stdout.write(`  ok  ${name}.json — re-derived identically\n`);
    } else {
      failures.push(`${name}.json has drifted: ${found}`);
      process.stdout.write(`  FAIL ${name}.json — ${found}\n`);
    }
  }
} finally {
  // Unconditionally, and after a failure as readily as after a pass: the stored report is
  // the committed artifact, and a drifted one is a finding to be read and committed
  // deliberately, not a diff this gate leaves behind in someone's working tree.
  for (const [name, { path, text }] of stored) {
    try {
      if (readFileSync(path, "utf8") !== text) writeFileSync(path, text);
    } catch (cause) {
      process.stdout.write(`  FAIL could not restore ${name}.json: ${cause}\n`);
      process.exitCode = 1;
    }
  }
}

process.stdout.write(
  `\n  ${DETERMINISTIC.length} report(s) re-derived; latency.json excluded, being a property` +
    " of the machine\n",
);

if (failures.length > 0) {
  process.stdout.write(
    `\n${failures.length} problem(s):\n${failures.map((line) => `  ${line}`).join("\n")}\n\n` +
      "A drifted report is not a failing test. The readme's figures are checked against\n" +
      "these files by `verify:docs`, so the prose and the file agree while both describe\n" +
      "code that no longer exists. Re-run `pnpm eval:all`, read what moved, and commit it\n" +
      "with the reason — the numbers are pre-registered, so a change to one is a finding.\n",
  );
  process.exit(1);
}
process.stdout.write("\nEvery published figure is still what the code produces.\n");
